/* @lc app=leetcode id=3291 lang=kotlin */ class Solution { fun minValidStrings(words: Array<String>, target: String): Int = (words.sumOf { it.length } + 1).let { N -> IntArray(26 * N).let { go -> IntArray(N).let { fail -> IntArray(N).let { dep -> IntArray(1) { 1 }.let { cnt -> words.forEach { w -> w.fold(0 to 0) { (node, d), c -> (node * 26 + (c - 'a')).let { e -> (if (go[e] != 0) go[e] else (cnt[0]++).also { go[e] = it }.also { dep[it] = d + 1 }) to d + 1 } } }.let { generateSequence((0 until 26).map { go[it] }.filter { it != 0 }) { f -> f.flatMap { u -> (0 until 26).mapNotNull { c -> go[u * 26 + c].let { v -> if (v != 0) v.also { fail[v] = go[fail[u] * 26 + c] } else go.set(u * 26 + c, go[fail[u] * 26 + c]).let { null } } } }.takeIf { it.isNotEmpty() } }.count().let { target.runningFold(0) { s, ch -> go[s * 26 + (ch - 'a')] }.drop(1).map { dep[it] }.let { dp -> target.length.let { n -> (1..n).map { it - dp[it - 1] }.reversed().runningFold(Int.MAX_VALUE) { m, x -> minOf(m, x) }.drop(1).reversed().let { sm -> generateSequence(n) { r -> if (r <= 0) null else sm[r - 1].takeIf { it < r } }.toList().let { l -> if (l.last() <= 0) l.size - 1 else -1 } } } } } } } } } } } }